// The generated entry of a craft draft: a board that shows each sketch next to what it must fit.

import { type CraftSubject, SKETCHES, type Sketch } from './draft.ts';

const BANNER =
  '// Generated by kitvas for a craft draft. Do not edit: kitvas rewrites it when the draft is checked or built.';

export type CraftEntryInput = {
  name: string;
  subject: CraftSubject;
  /** The picked sketch; the board shows only it. `null` shows all three. */
  picked: Sketch | null;
  /** Names of the kit's icons, from `kit.icons`; only the first 6 are shown. Empty: no kit row. */
  kitIcons: string[];
  /** The kit's icon component; `Icon` when omitted. */
  iconComponent?: string;
};

const KIT_ICON_LIMIT = 6;
const ICON_SIZES = [16, 24, 32] as const;
const LOGO_SIZES = [16, 32] as const;
const GROUNDS = ['light', 'dark'] as const;
const TONES = ['colour', 'mono'] as const;

const sketchesOf = (picked: Sketch | null): readonly Sketch[] =>
  picked === null ? SKETCHES : [picked];

const pad = (depth: number): string => '  '.repeat(depth);

function imports(input: CraftEntryInput, shown: readonly Sketch[], icon: string): string[] {
  const lines = shown.map((sketch) => {
    const names =
      input.subject === 'component' ? `${input.name}${sketch}Example` : `${input.name}${sketch}`;
    return `import { ${names} } from './sketches/${sketch}.tsx';`;
  });
  if (input.subject === 'icon' && input.kitIcons.length > 0) {
    lines.push(`import { ${icon} } from '@kit';`);
  }
  return lines;
}

function groundBlock(ground: string, body: string[], depth: number): string[] {
  return [
    `${pad(depth)}<div className="craft-ground craft-ground--${ground}">`,
    ...body.map((line) => `${pad(1)}${line}`),
    `${pad(depth)}</div>`,
  ];
}

function iconBody(input: CraftEntryInput, sketch: Sketch, icon: string, depth: number): string[] {
  const component = `${input.name}${sketch}`;
  const lines = ICON_SIZES.map((size) => `${pad(depth)}<${component} size={${size}} />`);
  for (const kitName of input.kitIcons.slice(0, KIT_ICON_LIMIT)) {
    const quoted = JSON.stringify(kitName);
    lines.push(`${pad(depth)}<span data-kit-icon=${quoted}><${icon} name=${quoted} /></span>`);
  }
  return lines;
}

function logoBody(input: CraftEntryInput, sketch: Sketch, tone: string, depth: number): string[] {
  const component = `${input.name}${sketch}`;
  return [
    ...LOGO_SIZES.map((size) => `${pad(depth)}<${component} tone="${tone}" size={${size}} />`),
    `${pad(depth)}<${component} tone="${tone}" />`,
  ];
}

function sketchBlock(input: CraftEntryInput, sketch: Sketch, icon: string): string[] {
  const out = [
    `      <section className="craft-sketch" data-craft-sketch="${sketch}">`,
    `        <h2 className="craft-caption">${input.name} · ${sketch}</h2>`,
  ];
  if (input.subject === 'component') {
    out.push(`        <${input.name}${sketch}Example />`);
  } else if (input.subject === 'icon') {
    for (const ground of GROUNDS) {
      out.push(...groundBlock(ground, iconBody(input, sketch, icon, 1), 4).map((l) => `  ${l}`));
    }
  } else {
    for (const tone of TONES) {
      for (const ground of GROUNDS) {
        out.push(...groundBlock(ground, logoBody(input, sketch, tone, 1), 4).map((l) => `  ${l}`));
      }
    }
  }
  out.push('      </section>');
  return out;
}

export function craftEntryTsx(input: CraftEntryInput): string {
  const shown = sketchesOf(input.picked);
  const icon = input.iconComponent ?? 'Icon';
  return [
    BANNER,
    ...imports(input, shown, icon),
    '',
    'export type DraftProps = { state: string };',
    '',
    'export function Draft(_props: DraftProps) {',
    '  return (',
    '    <>',
    `      <main className="craft-board" data-craft-subject="${input.subject}">`,
    ...shown.flatMap((sketch) => sketchBlock(input, sketch, icon).map((line) => `  ${line}`)),
    '      </main>',
    '    </>',
    '  );',
    '}',
    '',
  ].join('\n');
}

/** The board's layout. Spacing and text colour come from kit tokens; the grounds are plain white and near black. */
export function craftEntryScss(): string {
  return [
    BANNER,
    '.craft-board {',
    '  display: flex;',
    '  flex-wrap: wrap;',
    '  gap: var(--kit-space-8);',
    '  padding: var(--kit-space-8);',
    '  font-family: var(--kit-font-body);',
    '  color: var(--kit-color-ink);',
    '}',
    '',
    '.craft-sketch {',
    '  display: flex;',
    '  flex-direction: column;',
    '  gap: var(--kit-space-8);',
    '}',
    '',
    '.craft-caption {',
    '  margin: 0;',
    '}',
    '',
    '.craft-ground {',
    '  display: flex;',
    '  flex-wrap: wrap;',
    '  align-items: center;',
    '  gap: var(--kit-space-8);',
    '  padding: var(--kit-space-8);',
    '}',
    '',
    '.craft-ground--light {',
    '  background: #fff;',
    '  color: #111;',
    '}',
    '',
    '.craft-ground--dark {',
    '  background: #111;',
    '  color: #fff;',
    '}',
    '',
  ].join('\n');
}
